165	    private SimpleToken doNextToken(String expression, int index, boolean allowEscape, TokenType... filters) {
166	        boolean numericAllowed = acceptType(TokenType.numericValue, filters);
167	        if (numericAllowed) {
168	            // is it a numeric value
169	            StringBuilder sb = new StringBuilder(256);
170	            index = repositionIndex(expression, index, sb);
171	            if (!sb.isEmpty()) {
172	                return new SimpleToken(new SimpleTokenType(TokenType.numericValue, sb.toString()), index);
173	            }
174	        }
175	
176	        boolean escapeAllowed = allowEscape && acceptType(TokenType.escape, filters);
177	        if (escapeAllowed) {
178	            char ch = expression.charAt(index);
179	            boolean escaped = '\\' == ch;
180	            if (escaped && index < expression.length() - 1) {
181	                return fromEscaped(expression, index, ch);
182	            }
183	        }
184	
185	        // it could be any of the known tokens
186	        String text = expression.substring(index);
187	        for (int i = 0; i < NUMBER_OF_TOKENS; i++) {
188	            SimpleTokenType token = KNOWN_TOKENS[i];
189	            if (acceptType(token.getType(), filters)
190	                    && acceptToken(token, text, expression, index)) {
191	                onToken(token, index);
