    /**
     * Does the expression include an escape tokens.
     *
     * @param  expression the expression
     * @return            <tt>true</tt> if one or more escape tokens is included in the expression
     */
    public static boolean hasEscapeToken(String expression) {
        if (expression != null) {
            return expression.contains("\\n") || expression.contains("\\t") || expression.contains("\\r")
                    || expression.contains("\\}");
        }
        return false;
    }

    /**
     * Create the next token
     *
     * @param  expression  the input expression
     * @param  index       the current index
     * @param  allowEscape whether to allow escapes
     * @param  filter      defines the accepted token types to be returned (character is always used as fallback)
     * @return             the created token, will always return a token
     */
    public SimpleToken nextToken(String expression, int index, boolean allowEscape, TokenType... filter) {
        return doNextToken(expression, index, allowEscape, filter);
    }

    /**
     * Create the next token
     *
     * @param  expression  the input expression
     * @param  index       the current index
     * @param  allowEscape whether to allow escapes
     * @return             the created token will always return a token
     */
    public SimpleToken nextToken(String expression, int index, boolean allowEscape) {
        return doNextToken(expression, index, allowEscape);
    }

    private SimpleToken doNextToken(String expression, int index, boolean allowEscape, TokenType... filters) {
        boolean numericAllowed = acceptType(TokenType.numericValue, filters);
        if (numericAllowed) {
            // is it a numeric value
            StringBuilder sb = new StringBuilder(256);
            index = repositionIndex(expression, index, sb);
            if (!sb.isEmpty()) {
                return new SimpleToken(new SimpleTokenType(TokenType.numericValue, sb.toString()), index);
            }
        }

        boolean escapeAllowed = allowEscape && acceptType(TokenType.escape, filters);
        if (escapeAllowed) {
            char ch = expression.charAt(index);
            boolean escaped = '\\' == ch;
            if (escaped && index < expression.length() - 1) {
                return fromEscaped(expression, index, ch);
            }
        }

        // it could be any of the known tokens
        String text = expression.substring(index);
        for (int i = 0; i < NUMBER_OF_TOKENS; i++) {
            SimpleTokenType token = KNOWN_TOKENS[i];
            if (acceptType(token.getType(), filters)
                    && acceptToken(token, text, expression, index)) {
                onToken(token, index);
                return new SimpleToken(token, index);
            }
        }

        SimpleToken custom = customToken(expression, index, allowEscape, filters);
        if (custom != null) {
            onToken(custom.getType(), index);
            return custom;
        }

        // fallback and create a character token
        char ch = expression.charAt(index);
        return new SimpleToken(new SimpleTokenType(TokenType.character, String.valueOf(ch)), index);
    }

    protected SimpleToken customToken(String expression, int index, boolean allowEscape, TokenType... filters) {
        return null;
    }

    protected void onToken(SimpleTokenType token, int index) {
        // noop
    }

    private static int repositionIndex(String expression, int index, StringBuilder sb) {
        boolean digit = true;
        while (digit && index < expression.length()) {
            digit = Character.isDigit(expression.charAt(index));
            if (digit) {
                char ch = expression.charAt(index);
                sb.append(ch);
                index++;
                continue;
            }
            // is it a dot or comma as part of a floating point number
            boolean decimalSeparator = '.' == expression.charAt(index) || ',' == expression.charAt(index);
            if (decimalSeparator && !sb.isEmpty()) {
                char ch = expression.charAt(index);
                sb.append(ch);
                index++;
                // assume its still a digit
                digit = true;
                continue;
            }
        }
        return index;
    }

    private static SimpleToken fromEscaped(String expression, int index, char ch) {
        StringBuilder sb = new StringBuilder(256);

        // grab next character to escape
        char next = expression.charAt(++index);
        // special for new line, tabs and carriage return
        boolean special = false;
        if ('n' == next) {
            sb.append("\n");
            special = true;
        } else if ('t' == next) {
            sb.append("\t");
            special = true;
        } else if ('r' == next) {
            sb.append("\r");
            special = true;
        } else if ('}' == next) {
            sb.append("}");
            special = true;
        } else {
            // not special just a regular character
            sb.append(ch);
        }

        // force 2 as length if special
        return new SimpleToken(new SimpleTokenType(TokenType.character, sb.toString()), index, special ? 2 : 1);
    }

    protected static boolean acceptType(TokenType type, TokenType... filters) {
        if (filters == null || filters.length == 0) {
            return true;
        }
        for (TokenType filter : filters) {
            if (type == filter) {
                return true;
            }
        }
        return false;
    }

    protected static boolean acceptToken(SimpleTokenType token, String text, String expression, int index) {
        if (token.isUnary() && text.startsWith(token.getValue())) {
            return evalUnary(token, text, expression, index);
        }
        if (token.isBinary()) {
            return evalBinary(token, text, expression, index);
        }
        if (token.isOther()) {
            return evalOther(token, text, expression, index);
        }
        if (token.isTernary()) {
            return evalTernary(token, text, expression, index);
        }

        return text.startsWith(token.getValue());
    }

    private static boolean evalBinary(SimpleTokenType token, String text, String expression, int index) {
        return evalSurroundedBySpace(token, text, expression, index);
    }

    private static boolean evalOther(SimpleTokenType token, String text, String expression, int index) {
        return evalSurroundedBySpace(token, text, expression, index);
    }

    private static boolean evalTernary(SimpleTokenType token, String text, String expression, int index) {
        return evalSurroundedBySpace(token, text, expression, index);
    }

    /**
     * Checks that the token appears surrounded by spaces: "exp1 op exp2". Used by all infix operators (binary, other,
     * ternary).
     */
    private static boolean evalSurroundedBySpace(SimpleTokenType token, String text, String expression, int index) {
        int len = token.getValue().length();
        if (index < 2 || len >= text.length() - 1) {
            return false;
        }
        String previousOne = expression.substring(index - 1, index);
        String afterOne = text.substring(len, len + 1);
        return " ".equals(previousOne) && " ".equals(afterOne) && text.substring(0, len).equals(token.getValue());
    }

    private static boolean evalUnary(SimpleTokenType token, String text, String expression, int index) {
        int endLen = 1;

        // special check for unary as the previous must be a function end, and the next a whitespace
        // to ensure unary operators is only applied on functions as intended
        int len = token.getValue().length();

        String previous = "";
        if (index - endLen >= 0) {
            previous = expression.substring(index - endLen, index);
        }
        String after = text.substring(len);
        boolean whiteSpace = ObjectHelper.isEmpty(after) || after.startsWith(" ");
        boolean functionEnd = previous.equals("}");
        return functionEnd && whiteSpace;
    }

}

